create or replace function catalog._normalize_product_maintenance_images(p_images jsonb)
returns jsonb
language plpgsql
stable
set search_path = catalog, pg_temp
as $$
declare
  v_images jsonb := coalesce(p_images, '[]'::jsonb);
  v_has_primary boolean := false;
  v_first_key text;
begin
  if jsonb_typeof(v_images) <> 'array' then
    raise exception 'validation_exception: Images must be an array.';
  end if;

  select exists (
    select 1
    from jsonb_array_elements(v_images) image
    where coalesce((image ->> 'is_primary')::boolean, false)
  )
  into v_has_primary;

  if v_has_primary or jsonb_array_length(v_images) = 0 then
    return v_images;
  end if;

  select image ->> 'storage_key'
  into v_first_key
  from jsonb_array_elements(v_images) image
  order by coalesce((image ->> 'sort_order')::integer, 0), image ->> 'storage_key'
  limit 1;

  return (
    select jsonb_agg(
      case
        when image ->> 'storage_key' = v_first_key
          then jsonb_set(image, '{is_primary}', 'true'::jsonb, true)
        else jsonb_set(image, '{is_primary}', 'false'::jsonb, true)
      end
      order by coalesce((image ->> 'sort_order')::integer, 0), image ->> 'storage_key'
    )
    from jsonb_array_elements(v_images) image
  );
end;
$$;

create or replace function catalog._refresh_product_readiness(
  p_tenant_id uuid,
  p_product_id uuid
)
returns table (
  readiness_status text,
  readiness_blockers jsonb
)
language plpgsql
security definer
set search_path = catalog, pg_temp
as $$
declare
  v_facts record;
  v_blockers jsonb := '[]'::jsonb;
  v_required_count int := 0;
begin
  select *
  into v_facts
  from catalog._product_operational_facts(p_tenant_id, p_product_id);

  if not coalesce(v_facts.has_base_unit, false) then
    v_required_count := v_required_count + 1;
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'missing_base_unit',
      'message', 'Thiếu đơn vị cơ sở',
      'group', 'units'
    ));
  end if;

  if not coalesce(v_facts.has_images, false) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'missing_image',
      'message', 'Chưa có ảnh sản phẩm',
      'group', 'images'
    ));
  end if;

  if coalesce(v_facts.stock_mode, 'basic') = 'advanced' then
    if not coalesce(v_facts.has_stock, false) then
      v_required_count := v_required_count + 1;
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'pending_stock_from_inventory',
        'message', 'Chờ dữ liệu tồn kho từ Inventory',
        'group', 'stock'
      ));
    end if;
  elsif not coalesce(v_facts.has_stock, false) then
    v_required_count := v_required_count + 1;
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'missing_stock',
      'message', 'Thiếu tồn kho ban đầu',
      'group', 'stock'
    ));
  end if;

  if coalesce(v_facts.base_price_mode, 'manual') = 'costing_module' then
    if not coalesce(v_facts.has_base_price, false) then
      v_required_count := v_required_count + 1;
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'pending_base_price_from_costing',
        'message', 'Chờ giá cơ sở từ Costing',
        'group', 'basePrice'
      ));
    end if;
  elsif not coalesce(v_facts.has_base_price, false) then
    v_required_count := v_required_count + 1;
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'missing_price',
      'message', 'Thiếu giá cơ sở',
      'group', 'basePrice'
    ));
  end if;

  if not coalesce(v_facts.has_price_band, false) then
    v_required_count := v_required_count + 1;
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'missing_price_band',
      'message', 'Thiếu khung giá bán',
      'group', 'priceBand'
    ));
  end if;

  if not coalesce(v_facts.has_required_custom_fields, true) then
    v_required_count := v_required_count + 1;
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'missing_required_custom_fields',
      'message', 'Thiếu thông tin bổ sung bắt buộc',
      'group', 'customFields'
    ));
  end if;

  readiness_status := case
    when v_required_count = 0 then 'ready_to_sell'
    else 'incomplete'
  end;
  readiness_blockers := v_blockers;

  insert into catalog.product_readiness (
    product_id,
    tenant_id,
    status,
    blockers,
    updated_at
  )
  values (
    p_product_id,
    p_tenant_id,
    readiness_status::catalog.product_readiness_status,
    readiness_blockers,
    now()
  )
  on conflict (product_id) do update
  set status = excluded.status,
      blockers = excluded.blockers,
      updated_at = excluded.updated_at;

  return next;
end;
$$;

create or replace function catalog._product_maintenance_result_row(
  p_tenant_id uuid,
  p_product_id uuid
)
returns table (
  product_id uuid,
  name text,
  trade_name text,
  sku text,
  barcode text,
  description text,
  note text,
  business_status text,
  is_soft_deleted boolean,
  primary_image_url text,
  images jsonb,
  readiness_status text,
  readiness_blockers jsonb,
  version integer
)
language sql
stable
security definer
set search_path = catalog, pg_temp
as $$
  select
    p.id as product_id,
    p.name,
    p.trade_name,
    p.sku,
    p.barcode,
    p.description,
    p.note,
    p.business_status::text,
    (p.deleted_at is not null) as is_soft_deleted,
    (
      select coalesce(i.file_url, i.storage_key)
      from catalog.product_images i
      where i.tenant_id = p_tenant_id
        and i.product_id = p_product_id
        and i.is_primary = true
      order by i.sort_order asc, i.created_at asc
      limit 1
    ) as primary_image_url,
    coalesce((
      select jsonb_agg(coalesce(i.file_url, i.storage_key) order by i.sort_order asc, i.created_at asc)
      from catalog.product_images i
      where i.tenant_id = p_tenant_id
        and i.product_id = p_product_id
    ), '[]'::jsonb) as images,
    r.status::text as readiness_status,
    coalesce(r.blockers, '[]'::jsonb) as readiness_blockers,
    p.version
  from catalog.products p
  left join catalog.product_readiness r
    on r.product_id = p.id
   and r.tenant_id = p.tenant_id
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id;
$$;

create or replace function catalog.update_product_profile(
  p_tenant_id uuid,
  p_product_id uuid,
  p_name text,
  p_actor_id uuid default auth.uid(),
  p_trade_name text default null,
  p_sku text default null,
  p_barcode text default null,
  p_description text default null,
  p_note text default null,
  p_expected_version integer default null
)
returns table (
  product_id uuid,
  name text,
  trade_name text,
  sku text,
  barcode text,
  description text,
  note text,
  business_status text,
  is_soft_deleted boolean,
  primary_image_url text,
  images jsonb,
  readiness_status text,
  readiness_blockers jsonb,
  version integer
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_product catalog.products%rowtype;
  v_sku_normalized text;
  v_barcode_normalized text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.update') then
    raise exception 'permission denied: catalog.product.update';
  end if;

  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'validation_exception: Product name is required.';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
  for update;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.deleted_at is not null then
    raise exception 'product is soft-deleted and cannot be updated';
  end if;

  if p_expected_version is not null and p_expected_version <> v_product.version then
    raise exception 'stale_product_version: expected=% current=%',
      p_expected_version,
      v_product.version;
  end if;

  v_sku_normalized := nullif(lower(btrim(coalesce(p_sku, ''))), '');
  v_barcode_normalized := nullif(btrim(coalesce(p_barcode, '')), '');

  if v_sku_normalized is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.sku_normalized = v_sku_normalized
  ) then
    raise exception 'duplicate sku';
  end if;

  if v_barcode_normalized is not null and exists (
    select 1
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.id <> p_product_id
      and p.barcode_normalized = v_barcode_normalized
  ) then
    raise exception 'duplicate barcode';
  end if;

  update catalog.products
  set name = btrim(p_name),
      trade_name = nullif(btrim(coalesce(p_trade_name, '')), ''),
      sku = nullif(btrim(coalesce(p_sku, '')), ''),
      sku_normalized = v_sku_normalized,
      barcode = nullif(btrim(coalesce(p_barcode, '')), ''),
      barcode_normalized = v_barcode_normalized,
      description = nullif(btrim(coalesce(p_description, '')), ''),
      note = nullif(btrim(coalesce(p_note, '')), ''),
      updated_at = now(),
      updated_by = p_actor_id,
      version = catalog.products.version + 1
  where tenant_id = p_tenant_id
    and id = p_product_id;

  perform * from catalog._refresh_product_readiness(p_tenant_id, p_product_id);

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'UPDATED_PROFILE',
    jsonb_build_object(
      'before', jsonb_build_object(
        'name', v_product.name,
        'trade_name', v_product.trade_name,
        'sku', v_product.sku,
        'barcode', v_product.barcode,
        'description', v_product.description,
        'note', v_product.note
      ),
      'after', jsonb_build_object(
        'name', btrim(p_name),
        'trade_name', nullif(btrim(coalesce(p_trade_name, '')), ''),
        'sku', nullif(btrim(coalesce(p_sku, '')), ''),
        'barcode', nullif(btrim(coalesce(p_barcode, '')), ''),
        'description', nullif(btrim(coalesce(p_description, '')), ''),
        'note', nullif(btrim(coalesce(p_note, '')), '')
      )
    ),
    p_actor_id
  );

  return query
  select * from catalog._product_maintenance_result_row(p_tenant_id, p_product_id);
exception
  when unique_violation then
    if v_sku_normalized is not null and exists (
      select 1 from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.id <> p_product_id
        and p.sku_normalized = v_sku_normalized
    ) then
      raise exception 'duplicate sku';
    end if;
    if v_barcode_normalized is not null and exists (
      select 1 from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.id <> p_product_id
        and p.barcode_normalized = v_barcode_normalized
    ) then
      raise exception 'duplicate barcode';
    end if;
    raise;
end;
$$;

create or replace function catalog.update_product_images(
  p_tenant_id uuid,
  p_product_id uuid,
  p_images jsonb default '[]'::jsonb,
  p_actor_id uuid default auth.uid(),
  p_expected_version integer default null
)
returns table (
  product_id uuid,
  images jsonb,
  primary_image_url text,
  readiness_status text,
  readiness_blockers jsonb,
  version integer
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
#variable_conflict use_column
declare
  v_product catalog.products%rowtype;
  v_images jsonb;
  v_image jsonb;
  v_storage_key text;
  v_slot_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.update') then
    raise exception 'permission denied: catalog.product.update';
  end if;

  select *
  into v_product
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id
  for update;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product.deleted_at is not null then
    raise exception 'product is soft-deleted and cannot be updated';
  end if;

  if p_expected_version is not null and p_expected_version <> v_product.version then
    raise exception 'stale_product_version: expected=% current=%',
      p_expected_version,
      v_product.version;
  end if;

  v_images := catalog._normalize_product_maintenance_images(p_images);

  if jsonb_array_length(v_images) > 8 then
    raise exception 'validation_exception: Chỉ được tải lên tối đa 8 ảnh.';
  end if;

  delete from catalog.product_images pi
  where pi.tenant_id = p_tenant_id
    and pi.product_id = p_product_id;

  for v_image in select * from jsonb_array_elements(v_images)
  loop
    v_storage_key := nullif(btrim(coalesce(v_image ->> 'storage_key', '')), '');
    if v_storage_key is null then
      raise exception 'validation_exception: Image storage key is required.';
    end if;

    v_slot_id := nullif(v_image ->> 'slot_id', '')::uuid;
    if v_slot_id is not null then
      perform catalog._consume_image_upload_slot(
        p_tenant_id,
        v_storage_key,
        p_actor_id
      );
    end if;

    insert into catalog.product_images (
      id,
      tenant_id,
      product_id,
      storage_key,
      file_url,
      is_primary,
      sort_order,
      processing_status,
      upload_slot_id
    )
    values (
      case
        when coalesce(v_image ->> 'image_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (v_image ->> 'image_id')::uuid
        else gen_random_uuid()
      end,
      p_tenant_id,
      p_product_id,
      v_storage_key,
      nullif(btrim(coalesce(v_image ->> 'url', '')), ''),
      coalesce((v_image ->> 'is_primary')::boolean, false),
      coalesce((v_image ->> 'sort_order')::integer, 0),
      'ready',
      v_slot_id
    );
  end loop;

  update catalog.products
  set updated_at = now(),
      updated_by = p_actor_id,
      version = catalog.products.version + 1
  where tenant_id = p_tenant_id
    and id = p_product_id;

  perform * from catalog._refresh_product_readiness(p_tenant_id, p_product_id);

  insert into catalog.product_change_history (tenant_id, product_id, action, payload, actor_id)
  values (
    p_tenant_id,
    p_product_id,
    'UPDATED_IMAGES',
    jsonb_build_object('images', v_images),
    p_actor_id
  );

  return query
  select
    p.product_id,
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'image_id', i.id,
        'storage_key', i.storage_key,
        'url', i.file_url,
        'is_primary', i.is_primary,
        'sort_order', i.sort_order
      ) order by i.sort_order asc, i.created_at asc)
      from catalog.product_images i
      where i.tenant_id = p_tenant_id
        and i.product_id = p_product_id
    ), '[]'::jsonb) as images,
    p.primary_image_url,
    p.readiness_status,
    p.readiness_blockers,
    p.version
  from catalog._product_maintenance_result_row(p_tenant_id, p_product_id) p;
end;
$$;

create or replace function catalog.request_product_maintenance_image_upload(
  p_tenant_id uuid,
  p_product_id uuid,
  p_file_name text,
  p_content_type text,
  p_byte_size bigint,
  p_actor_id uuid default auth.uid()
)
returns table (
  slot_id uuid,
  storage_key text,
  expires_at timestamptz
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_slot_id uuid;
  v_ext text;
  v_storage_key text;
  v_expires_at timestamptz;
  v_product_deleted_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.update') then
    raise exception 'permission denied: catalog.product.update';
  end if;

  select p.deleted_at
  into v_product_deleted_at
  from catalog.products p
  where p.tenant_id = p_tenant_id
    and p.id = p_product_id;

  if not found then
    raise exception 'product not found';
  end if;

  if v_product_deleted_at is not null then
    raise exception 'product is soft-deleted and cannot be updated';
  end if;

  if p_content_type not in ('image/jpeg', 'image/png', 'image/webp') then
    raise exception 'validation_exception: Unsupported image content type.';
  end if;

  if p_byte_size <= 0 then
    raise exception 'validation_exception: Image byte size must be positive.';
  end if;

  if p_byte_size > 10485760 then
    raise exception 'validation_exception: Image exceeds maximum allowed size.';
  end if;

  v_ext := case p_content_type
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'image/webp' then 'webp'
    else 'bin'
  end;
  v_slot_id := gen_random_uuid();
  v_expires_at := now() + interval '1 hour';
  v_storage_key := p_tenant_id::text || '/staging/' || v_slot_id::text || '/original.' || v_ext;

  insert into catalog.image_upload_slots (
    id,
    tenant_id,
    storage_key,
    actor_id,
    file_name,
    content_type,
    byte_size,
    expires_at
  )
  values (
    v_slot_id,
    p_tenant_id,
    v_storage_key,
    p_actor_id,
    p_file_name,
    p_content_type,
    p_byte_size,
    v_expires_at
  );

  slot_id := v_slot_id;
  storage_key := v_storage_key;
  expires_at := v_expires_at;
  return next;
end;
$$;

